(async () => {
  // OverTime macro for the Sucking Ground effect, run at the end of each of the creature's turns.
  // Raises the escape DC by 5 and, after two turns, starts Suffocation (removed when the creature escapes).
  const target = typeof workflow !== "undefined" ? workflow?.targets?.first?.() : undefined;
  const subject = target?.actor ?? (typeof actor !== "undefined" ? actor : null);
  if (!subject) return {};

  const effect = subject.effects.find(
    (e) => !e.disabled && e.getFlag("elkan5e", "suckingGround") !== undefined,
  );
  if (!effect) return {};

  const turns = Number(effect.getFlag("elkan5e", "suckingGround") ?? 0) + 1;
  await effect.update({
    name: `Sucking Ground (Escape DC ${10 + 5 * turns})`,
    "flags.elkan5e.suckingGround": turns,
  });

  if (turns < 2 || subject.statuses.has("suffocation")) return {};
  const suffocation = await subject.toggleStatusEffect("suffocation", { active: true });
  if (suffocation instanceof ActiveEffect) {
    // dnd5e deletes dependents with their parent, so escaping also ends the suffocation.
    const dependents = effect.getFlag("dnd5e", "dependents") ?? [];
    await effect.setFlag("dnd5e", "dependents", [...dependents, { uuid: suffocation.uuid }]);
  }
  return {};
})();
